// RegisterFamilyRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterFamilyRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer FamilyRetrievalObserver, construct func(foundation.Resolver) (func() FamilyRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (FamilyRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Family], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Family, FamilyRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Family]{}, err
	}
	var allHooks []FamilyRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Family]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Family]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Family]{}, err
	}
	return foundryquery.RetrievalHooks[Family]{Retrieved: func(ctx context.Context, executor database.Executor, item Family) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

